"""T-010: build one Luau Execution script that runs every Lune spec (tests/*.spec.luau) inside the real
Roblox engine, then the T-005b smoke test. Specs keep their Lune `require("../src/shared/X")` paths; the
runner maps them onto ReplicatedStorage.Shared. Usage: python3 scripts/cloud_runner.py > build/cloud_runner.luau"""
import glob, os

HEADER = '''--!nocheck
-- Generated by scripts/cloud_runner.py (T-010). Do not edit.
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local function cloudRequire(path)
	local rel = string.match(path, "^%.%./src/shared/(.+)$")
	if not rel then
		error("cloud runner: unsupported require " .. path)
	end
	local inst = ReplicatedStorage:WaitForChild("Shared", 10)
	for part in string.gmatch(rel, "[^/]+") do
		inst = inst:WaitForChild(part, 10)
	end
	return require(inst)
end
local specs = {}
'''

FOOTER = '''
local passed, failed, failures = 0, 0, {}
for _, entry in specs do
	local ok, suite = pcall(entry.load, cloudRequire)
	if not ok then
		failed += 1
		table.insert(failures, entry.name .. " (load): " .. tostring(suite))
	else
		local names = {}
		for n in suite do
			table.insert(names, n)
		end
		table.sort(names)
		for _, n in names do
			local okTest, err = pcall(suite[n])
			if okTest then
				passed += 1
			else
				failed += 1
				table.insert(failures, entry.name .. " > " .. n .. ": " .. tostring(err))
			end
		end
	end
end
print(string.format("SPECS: %d passed, %d failed (%d specs)", passed, failed, #specs))
for i = 1, math.min(#failures, 10) do
	print("  FAIL " .. failures[i])
end

local packages = {}
for _, p in { { "Packages", "Signal" }, { "Packages", "Trove" } } do
	local ok = pcall(function()
		require(ReplicatedStorage:WaitForChild(p[1], 10):WaitForChild(p[2], 10))
	end)
	table.insert(packages, (ok and "PASS " or "FAIL ") .. p[2])
end
local okStore = pcall(function()
	require(game:GetService("ServerScriptService"):WaitForChild("ServerPackages", 10):WaitForChild("ProfileStore", 10))
end)
table.insert(packages, (okStore and "PASS " or "FAIL ") .. "ProfileStore")
print("PACKAGES: " .. table.concat(packages, ", "))

local smokeOk, smokeDetail = smoke()
local allPass = failed == 0 and smokeOk and not string.find(table.concat(packages, ","), "FAIL")
print(allPass and "CLOUD ALL: PASS" or "CLOUD ALL: FAIL")
return allPass, string.format("specs %d/%d | %s | %s", passed, passed + failed, table.concat(packages, ", "), smokeDetail)
'''


def build(root="."):
    out = [HEADER]
    for path in sorted(glob.glob(os.path.join(root, "tests", "*.spec.luau"))):
        body = open(path).read()
        name = os.path.basename(path)
        out.append(f'table.insert(specs, {{ name = "{name}", load = function(require)\n{body}\nend }})\n')
    smoke = open(os.path.join(root, "tests", "cloud", "smoke.luau")).read()
    out.append("local function smoke()\n" + smoke + "\nend\n")
    out.append(FOOTER)
    return "".join(out)


if __name__ == "__main__":
    print(build())